-- Diagnostic 005 : comptages seulement (aucune donnée exportée), toujours ROLLBACK
BEGIN;
CREATE TEMP TABLE d (matiere TEXT, ancien TEXT, chapitre TEXT) ON COMMIT DROP;
CREATE TEMP TABLE n ON COMMIT DROP AS
SELECT d.*,
  EXISTS (SELECT 1 FROM questions q WHERE q.enonce = d.ancien) AS exact,
  EXISTS (SELECT 1 FROM questions q WHERE regexp_replace(btrim(replace(q.enonce, chr(8217), '''')), '\s+', ' ', 'g')
                                      = regexp_replace(btrim(replace(d.ancien, chr(8217), '''')), '\s+', ' ', 'g')) AS normalise,
  EXISTS (SELECT 1 FROM questions q WHERE left(q.enonce, 40) = left(d.ancien, 40)) AS debut40
FROM d;
SELECT matiere, COUNT(*) AS total, SUM((NOT exact)::int) AS introuvables_exact,
       SUM((NOT exact AND normalise)::int) AS retrouves_normalise,
       SUM((NOT exact AND NOT normalise AND debut40)::int) AS retrouves_debut40
FROM n GROUP BY matiere ORDER BY introuvables_exact DESC;
SELECT COUNT(*) AS total_questions_prod FROM questions;
SELECT m.nom, COUNT(q.id) AS nb FROM questions q JOIN chapitres c ON c.id = q.chapitre_id JOIN matieres m ON m.id = c.matiere_id GROUP BY m.nom ORDER BY m.nom;
COMMIT;
